// Filter jobs with direct apply links
const jobs = [];

// Process Adzuna results
if ($input.item.json.results) {
  $input.item.json.results.forEach(job => {
    const redirectUrl = job.redirect_url || '';
    const isDirectApply = redirectUrl.includes('lever.co') || 
                          redirectUrl.includes('greenhouse.io') || 
                          redirectUrl.includes('workday') ||
                          redirectUrl.includes('getwork.com');

    if (isDirectApply) {
      jobs.push({
        job_title: job.title,
        company: job.company.display_name,
        location: job.location.display_name,
        source: 'Adzuna',
        apply_url: redirectUrl,
        application_type: 'Web Form',
        ats_platform: detectATS(redirectUrl),
        job_description: job.description,
        timestamp: new Date().toISOString()
      });
    }
  });
}

function detectATS(url) {
  if (url.includes('lever.co')) return 'Lever';
  if (url.includes('greenhouse.io')) return 'Greenhouse';
  if (url.includes('workday')) return 'Workday';
  return 'Other';
}

return jobs.map(job => ({ json: job }));

// Calculate match score based on skills alignment
const personalData = $input.item.json.personal_data;
const jobDesc = $input.item.json.job_description.toLowerCase();

const keySkills = [
  'embedded', 'flight software', 'aerospace', 'python', 'c/c++',
  'rtos', 'arm', 'cubeSat', 'avionics', 'machine learning'
];

let matchCount = 0;
keySkills.forEach(skill => {
  if (jobDesc.includes(skill.toLowerCase())) {
    matchCount++;
  }
});

const matchScore = Math.round((matchCount / keySkills.length) * 100);

return {
  json: {
    ...$input.item.json,
    match_score: matchScore,
    required_skills: extractSkills(jobDesc)
  }
};

function extractSkills(desc) {
  // Simple skill extraction - can be enhanced with LLM
  const skills = [];
  const skillPatterns = ['Python', 'C++', 'RTOS', 'Linux', 'Git', 'Docker'];
  skillPatterns.forEach(skill => {
    if (desc.includes(skill.toLowerCase())) {
      skills.push(skill);
    }
  });
  return skills.join(', ');
}
